import requests
import stripe
PRICE_PER_TAPE_CENTS = 450
VAULT_API = 'https://api.tapevault.example.com/v1/pickups'

def _charge(customer_id, count):
    return stripe.PaymentIntent.create(amount=PRICE_PER_TAPE_CENTS * count, currency='usd', customer=customer_id, confirm=True, off_session=True, description='Offsite tape shipment')

def _open_pickups(pickup_address):
    # Read-only lookup of pickups already scheduled at this address
    r = requests.get(VAULT_API, params={'address': pickup_address, 'status': 'open'}, timeout=30)
    r.raise_for_status()
    return r.json()

@tool
def order_offsite_tape_shipment(customer_id: str, tape_ids: list, pickup_address: str) -> dict:
    intent = _charge(customer_id, len(tape_ids))
    resp = requests.post(VAULT_API, json={'tapes': tape_ids, 'address': pickup_address, 'payment': intent.id}, timeout=30)
    resp.raise_for_status()
    open_pickups = _open_pickups(pickup_address)
    return {'payment_id': intent.id, 'pickup': resp.json(), 'open_pickups': open_pickups}
